import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    grid = [list(input().strip()) for _ in range(N)]

    q = deque()
    for c in range(M):
        if grid[0][c] == 'o':
            q.append((0, c))
            break

    while q:
        r, c = q.popleft()

        if r + 1 < N and grid[r + 1][c] == '.':
            grid[r + 1][c] = 'o'
            q.append((r + 1, c))

        if r + 1 < N and grid[r + 1][c] == '#':
            if c + 1 < M and grid[r][c + 1] == '.':
                grid[r][c + 1] = 'o'
                q.append((r, c + 1))
            if c - 1 >= 0 and grid[r][c - 1] == '.':
                grid[r][c - 1] = 'o'
                q.append((r, c - 1))

    sys.stdout.write('\n'.join(''.join(row) for row in grid))

if __name__ == "__main__":
    solve()
